-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["modules/era/lua/quests/jeuno/your_crystal_ball.lua"]={["Path"]="modules/era/lua/quests/jeuno/your_crystal_ball.lua",["SHA256"]="30ff0092950f83ecdeada207719e8cd914c856f0beeefd8ca9ef2e0784d3087a",["Text"]="-----------------------------------\n-- Your Crystal Ball\n-- Restores the JST midnight wait while the ahriman lens soaks in the Maze of Shakhrami.\n-- The June 17, 2014 version update shortened the wait to one minute.\n-- The update notes give no values; the JST midnight condition comes from the Japanese wiki.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/5214.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_your_crystal_ball', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/jeuno/Your_Crystal_Ball', function(quest)\n        local maze      = quest.sections[2][xi.zone.MAZE_OF_SHAKHRAMI]\n        local baseTrade = maze['Rockwell'].onTrade\n\n        -- The lens soaks overnight. Rockwell hands the sphere over at JST midnight.\n        maze['Rockwell'].onTrade = function(player, npc, trade)\n            local previousWait = quest:getVar(player, 'Wait')\n            local result       = baseTrade(player, npc, trade)\n\n            if quest:getVar(player, 'Wait') ~= previousWait then\n                quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n            end\n\n            return result\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/a_hard_days_knight.lua"]={["Path"]="modules/era/lua/quests/otherareas/a_hard_days_knight.lua",["SHA256"]="f5759a63c208da89c84c9abcf86e04ad3f7635ca2d0f002ebf528462220d4b39",["Text"]="-----------------------------------\n-- A Hard Day's Knight\n-- Removes the ability to obtain the Temple Knight Key.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/40059\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_a_hard_days_knight', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/A_Hard_Days_Knight', function(quest)\n        table.remove(quest.sections, 3)\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/better_the_demon_you_know.lua"]={["Path"]="modules/era/lua/quests/otherareas/better_the_demon_you_know.lua",["SHA256"]="d30ae7e05faca4824919adf0a2bc391a5c5f70993f29be6aff70d190e9c6d940",["Text"]="-----------------------------------\n-- Better the Demon You Know\n-- Restores the JST midnight wait before Koblakiq finishes reading the demon pen.\n-- The July 8, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_better_the_demon_you_know', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Better_The_Demon_You_Know', function(quest)\n        local oldton  = quest.sections[2][xi.zone.OLDTON_MOVALPOLOS]\n        local basePen = oldton.onEventFinish[22]\n\n        -- Koblakiq works on the pen overnight. He sends the player on at JST midnight.\n        oldton.onEventFinish[22] = function(player, csid, option, npc)\n            basePen(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/give_a_moogle_a_break.lua"]={["Path"]="modules/era/lua/quests/otherareas/give_a_moogle_a_break.lua",["SHA256"]="edf533785e8675d30ca5cc7be1abdd46e238eb25e7eed92117fbaad3ee349b84",["Text"]="-----------------------------------\n-- Give a Moogle a Break\n-- Restores the conquest tally wait before the Moogle offers the quest.\n-- Restores the JST midnight wait before the Moogle hands over the reward.\n-- The July 8, 2014 version update shortened both waits to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_give_a_moogle_a_break', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Give_a_Moogle_a_Break', function(quest)\n        -- Copy of the base check. The quest is offered at the next conquest tally.\n        quest.sections[1].check = function(player, status, vars)\n            local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.moghouse.inMogHouseInHomeNation(player) and\n                player:getFameLevel(player:getNation()) >= 3 and\n                quest:getLocalVar(player, 'mustZone') == 0 and\n                quest:getLocalVar(player, 'questSeen') == 0 and\n                bedPlacedTime ~= 0 and\n                bedPlacedTime < NextConquestTally() - utils.days(7) -- Module change\n        end\n\n        -- Every Mog House zone shares one section table. A wrapper would run the base handler once per zone.\n        for _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n            local section = quest.sections[2][zoneId]\n\n            -- Copy of the base handler. The reward is handed over at JST midnight.\n            section.onEventFinish[30007] = function(player, csid, option, npc)\n                player:tradeComplete()\n                quest:setVar(player, 'Prog', 1)\n                quest:setVar(player, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/inside_the_belly.lua"]={["Path"]="modules/era/lua/quests/otherareas/inside_the_belly.lua",["SHA256"]="c01dc36b243b9094904ed030e00b0a38d9c05cec6c79bc4714fc65c42836f40f",["Text"]="-----------------------------------\n-- Inside the Belly\n-- Restores Zaldon's trade list to the era of the newest enabled expansion.\n-- The quest launched with 18 fish. Version updates from 2009-11-10 onward grew the list.\n-- Each batch is gated on when the trade option was added, not on when its fish was implemented.\n--\n-- Source: https://www.playonline.com/pcd/verup/ff11/detail/5053/detail.html\n-- Source: https://wiki.ffo.jp/html/1338.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_inside_the_belly',\n    xi.pre(xi.expansion.WOTG) or\n    xi.pre(xi.expansion.ABYSSEA) or\n    xi.pre(xi.expansion.SOA) or\n    xi.pre(xi.expansion.ROV))\n\nlocal tradeBatches =\n{\n    -- Added 2009-11-10 and 2010-03-23.\n    {\n        blocked = xi.pre(xi.expansion.WOTG),\n        items =\n        {\n            xi.item.BLADEFISH_1,\n            xi.item.GAVIAL_FISH,\n            xi.item.VEYDAL_WRASSE_1,\n            xi.item.MORINABALIGI,\n            xi.item.TURNABALIGI,\n            xi.item.KALKANBALIGI,\n            xi.item.PTERYGOTUS,\n            xi.item.GERROTHORAX,\n            xi.item.PIRARUCU,\n            xi.item.MEGALODON,\n            xi.item.YAYINBALIGI,\n            xi.item.LAKERDA,\n            xi.item.KILICBALIGI,\n            xi.item.MONKE_ONKE_1,\n            xi.item.AHTAPOT,\n            xi.item.ARMORED_PISCES,\n            xi.item.MOLA_MOLA,\n        },\n    },\n\n    -- Added 2010-09-09 and 2010-12-07.\n    {\n        blocked = xi.pre(xi.expansion.ABYSSEA),\n        items =\n        {\n            xi.item.GUGRU_TUNA_1,\n            xi.item.ISTAVRIT_1,\n            xi.item.GIGANT_OCTOPUS_1,\n            xi.item.THREE_EYED_FISH_1,\n            xi.item.GIGANT_SQUID,\n            xi.item.RHINOCHIMERA_1,\n            xi.item.GRIMMONITE,\n            xi.item.TITANIC_SAWFISH,\n            xi.item.PELAZOEA,\n            xi.item.DORADO_GAR,\n            xi.item.CROCODILOS,\n        },\n    },\n\n    -- Added 2012-07-24, between Abyssea and SoA.\n    {\n        blocked = xi.pre(xi.expansion.SOA),\n        items =\n        {\n            xi.item.ABAIA,\n            xi.item.MATSYA,\n        },\n    },\n\n    -- Added 2015-06-25 and 2015-11-10.\n    {\n        blocked = xi.pre(xi.expansion.ROV),\n        items =\n        {\n            xi.item.SORYU,\n            xi.item.SEKIRYU,\n            xi.item.HAKURYU,\n            xi.item.FAR_EAST_PUFFER,\n        },\n    },\n}\n\nlocal blockedFish = {}\nfor _, batch in ipairs(tradeBatches) do\n    if batch.blocked then\n        for _, itemId in ipairs(batch.items) do\n            blockedFish[itemId] = true\n        end\n    end\nend\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Inside_the_Belly', function(quest)\n        -- Sections 2 and 3 take the fish trades (quest accepted and quest completed).\n        for _, sectionIdx in ipairs({ 2, 3 }) do\n            local zaldon      = quest.sections[sectionIdx][xi.zone.SELBINA]['Zaldon']\n            local baseOnTrade = zaldon.onTrade\n\n            -- A blocked fish returns nothing. Zaldon plays his default dialogue and the fish is kept.\n            zaldon.onTrade = function(player, npc, trade)\n                for itemSlot = 0, trade:getSlotCount() - 1 do\n                    if blockedFish[trade:getItemId(itemSlot)] then\n                        return\n                    end\n                end\n\n                return baseOnTrade(player, npc, trade)\n            end\n\n            -- The stock hint lists name only original and 2009-batch fish.\n            -- Events 163, 164, and 165 render a fixed count of names (5, 2+4, 2+6). An empty slot prints a blank name.\n            if xi.pre(xi.expansion.WOTG) then\n                zaldon.onTrigger = function(player, npc)\n                    local fishingSkill = xi.crafting.getTotalSkill(player, xi.skill.FISHING)\n\n                    local tier = 4\n\n                    if fishingSkill < 40 then\n                        tier = 1\n                    elseif fishingSkill < 50 then\n                        tier = 2\n                    elseif fishingSkill < 75 then\n                        tier = 3\n                    end\n\n                    local csTier =\n                    {\n                        {\n                            162,\n                            xi.item.GIANT_CATFISH_1,\n                            xi.item.DARK_BASS_1,\n                            xi.item.OGRE_EEL_1,\n                            xi.item.ZAFMLUG_BASS,\n                        },\n\n                        {\n                            163,\n                            xi.item.ZAFMLUG_BASS,\n                            xi.item.GIANT_DONKO_1,\n                            xi.item.BHEFHEL_MARLIN_1,\n                            xi.item.JUNGLE_CATFISH,\n                            xi.item.SILVER_SHARK,\n                        },\n\n                        {\n                            164,\n                            xi.item.JUNGLE_CATFISH,\n                            xi.item.EMPEROR_FISH,\n                            xi.item.SILVER_SHARK,\n                            xi.item.TAKITARO,\n                            xi.item.SEA_ZOMBIE,\n                            xi.item.GIANT_CHIRAI,\n                        },\n\n                        {\n                            165,\n                            xi.item.TAKITARO,\n                            xi.item.SEA_ZOMBIE,\n                            xi.item.TITANICTUS,\n                            xi.item.CAVE_CHERAX,\n                            xi.item.TRICORN,\n                            xi.item.RYUGU_TITAN,\n                            xi.item.LIK,\n                            xi.item.GUGRUSAURUS,\n                        },\n                    }\n\n                    return quest:event(unpack(csTier[tier]))\n                end\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/its_raining_mannequins.lua"]={["Path"]="modules/era/lua/quests/otherareas/its_raining_mannequins.lua",["SHA256"]="c5f3c0931d1d538ec06b4c41bf50190a8efe003002209161f615edcd299810fc",["Text"]="-----------------------------------\n-- It's Raining Mannequins!\n-- Restores the JST midnight wait while Fyi Chalmwoh assembles the mannequin.\n-- The June 17, 2014 version update shortened the wait to one minute.\n-- The update notes give no values; the JST midnight condition comes from the Japanese wiki.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/7101.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_its_raining_mannequins', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Its_Raining_Mannequins', function(quest)\n        local mhauraTrade  = quest.sections[4][xi.zone.MHAURA]\n        local mhauraReward = quest.sections[5][xi.zone.MHAURA]\n        local basePartsCS  = mhauraTrade.onEventFinish[309]\n\n        -- The parts are assembled overnight. The mannequin is collected at JST midnight.\n        mhauraTrade.onEventFinish[309] = function(player, csid, option, npc)\n            basePartsCS(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n\n        -- Copy of the base handler. 'Wait' now holds the due time rather than the time of the trade.\n        mhauraReward['Fyi_Chalmwoh'].onTrigger = function(player, npc)\n            if GetSystemTime() >= quest:getVar(player, 'Wait') then -- Module change\n                return quest:progressEvent(311)\n            else\n                return quest:event(310) -- Please wait\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/moogles_in_the_wild.lua"]={["Path"]="modules/era/lua/quests/otherareas/moogles_in_the_wild.lua",["SHA256"]="7a133e2be247e2410654fe8bf888dd89b6e3a1fa30aa4558658fed37a893826b",["Text"]="-----------------------------------\n-- Moogles in the Wild\n-- Restores the conquest tally wait before the Moogle offers the quest.\n-- Restores the JST midnight wait before the Moogle hands over the reward.\n-- The July 8, 2014 version update shortened both waits to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_moogles_in_the_wild', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/Moogles_in_the_Wild', function(quest)\n        -- Copy of the base check. The quest is offered at the next conquest tally.\n        quest.sections[1].check = function(player, status, vars)\n            local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC) and\n                xi.moghouse.inMogHouseInHomeNation(player) and\n                player:getFameLevel(player:getNation()) >= 7 and\n                quest:getLocalVar(player, 'mustZone') == 0 and\n                quest:getLocalVar(player, 'questSeen') == 0 and\n                bedPlacedTime ~= 0 and\n                bedPlacedTime < NextConquestTally() - utils.days(7) -- Module change\n        end\n\n        -- Every Mog House zone shares one section table. A wrapper would run the base handler once per zone.\n        for _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n            local section = quest.sections[2][zoneId]\n\n            -- Copy of the base handler. The reward is handed over at JST midnight.\n            section.onEventFinish[30015] = function(player, csid, option, npc)\n                player:tradeComplete()\n                quest:setVar(player, 'Prog', 1)\n                quest:setVar(player, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/otherareas/the_moogles_picnic.lua"]={["Path"]="modules/era/lua/quests/otherareas/the_moogles_picnic.lua",["SHA256"]="3ef574e1751b4e8ea36d19b08bbf5df20581bf13c2d1cb1481c7c6cf7f2d4f67",["Text"]="-----------------------------------\n-- The Moogle's Picnic!\n-- Restores the conquest tally wait before the Moogle offers the quest.\n-- Restores the JST midnight wait before the Moogle hands over the reward.\n-- The July 8, 2014 version update shortened both waits to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_the_moogles_picnic', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/otherAreas/The_Moogles_Picnic', function(quest)\n        -- Copy of the base check. The quest is offered at the next conquest tally.\n        quest.sections[1].check = function(player, status, vars)\n            local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK) and\n                xi.moghouse.inMogHouseInHomeNation(player) and\n                player:getFameLevel(player:getNation()) >= 5 and\n                quest:getLocalVar(player, 'mustZone') == 0 and\n                quest:getLocalVar(player, 'questSeen') == 0 and\n                bedPlacedTime ~= 0 and\n                bedPlacedTime < NextConquestTally() - utils.days(7) -- Module change\n        end\n\n        -- Every Mog House zone shares one section table. A wrapper would run the base handler once per zone.\n        for _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n            local section = quest.sections[2][zoneId]\n\n            -- Copy of the base handler. The reward is handed over at JST midnight.\n            section.onEventFinish[30011] = function(player, csid, option, npc)\n                player:tradeComplete()\n                quest:setVar(player, 'Prog', 1)\n                quest:setVar(player, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/a_thief_in_norg.lua"]={["Path"]="modules/era/lua/quests/outlands/a_thief_in_norg.lua",["SHA256"]="7ab3940cd9ee136582ff1ee7f8d62329d3ca50be50a80d8670d605b6d013bad8",["Text"]="-----------------------------------\n-- A Thief in Norg!? (SAM AF3)\n-- Restores the JST midnight wait before Jaucribaix repairs the charred helm.\n-- The July 8, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_a_thief_in_norg', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/SAM_AF3_A_Thief_in_Norg', function(quest)\n        local norg         = quest.sections[2][xi.zone.NORG]\n        local baseThreadCS = norg.onEventFinish[162]\n\n        -- The helm is repaired at JST midnight.\n        norg.onEventFinish[162] = function(player, csid, option, npc)\n            baseThreadCS(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/divine_might.lua"]={["Path"]="modules/era/lua/quests/outlands/divine_might.lua",["SHA256"]="dac5c32e9b17e6350bed108cf4fd15f95069b554cadafb08c2fe28ac73b3df44",["Text"]="-----------------------------------\n-- Divine Might\n-- Restores the clear full moon night, 00:00 to 03:00, at the Qu'Hau Spring.\n-- The June 7, 2016 version update widened the window to 18:00 through 06:00 and dropped the weather.\n-- Divine Might (Repeat) shares the spring and the window.\n-- The Ro'Maeve moongates, bridges and fountain are already restored by era_moongate_time.\n-- The weather check reads the zone. A scholar's storm does not close the spring.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/50760-Jun.-7-2016-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_divine_might', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/Divine_Might', function(quest)\n        local romaeve = quest.sections[2][xi.zone.ROMAEVE]\n\n        -- Copy of the base handler. The spring accepts the trade on a clear full moon night.\n        romaeve['QuHau_Spring'].onTrade = function(player, npc, trade)\n            local vanaHour = VanadielHour()\n            local weather  = player:getZone():getWeather() -- Module change\n\n            if\n                (getVanadielMoonCycle() == xi.moonCycle.FULL_MOON) and\n                (vanaHour >= 0 and vanaHour < 3) and -- Module change\n                (weather == xi.weather.NONE or weather == xi.weather.SUNSHINE) and -- Module change\n                npcUtil.tradeHasExactly(trade, { xi.item.BOTTLE_OF_ILLUMININK, xi.item.SHEET_OF_PARCHMENT })\n            then\n                return quest:progressEvent(7, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK)\n            end\n        end\n    end)\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/Divine_Might_Repeat', function(quest)\n        local romaeve = quest.sections[2][xi.zone.ROMAEVE]\n\n        -- Copy of the base handler. The window also gates the chunk of light ore trade.\n        romaeve['QuHau_Spring'].onTrade = function(player, npc, trade)\n            local vanaHour = VanadielHour()\n            local weather  = player:getZone():getWeather() -- Module change\n\n            if\n                (getVanadielMoonCycle() == xi.moonCycle.FULL_MOON) and\n                (vanaHour >= 0 and vanaHour < 3) and -- Module change\n                (weather == xi.weather.NONE or weather == xi.weather.SUNSHINE) -- Module change\n            then\n                if npcUtil.tradeHasExactly(trade, { xi.item.BOTTLE_OF_ILLUMININK, xi.item.SHEET_OF_PARCHMENT }) then\n                    return quest:progressEvent(7, xi.item.SHEET_OF_PARCHMENT, xi.item.BOTTLE_OF_ILLUMININK)\n                elseif\n                    not player:hasKeyItem(xi.keyItem.MOONLIGHT_ORE) and\n                    npcUtil.tradeHasExactly(trade, xi.item.CHUNK_OF_LIGHT_ORE)\n                then\n                    return quest:progressEvent(8)\n                end\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/the_kuftal_tour.lua"]={["Path"]="modules/era/lua/quests/outlands/the_kuftal_tour.lua",["SHA256"]="ee3b3f128758c9b9d49acfdcdc10206b72b46bb1a42801e5003c960ae9f007c6",["Text"]="-----------------------------------\n-- Module to change the party size requirements in 'The Kuftal Tour' quest to 6.\n-- Originally this quest required 6 players, but was dropped to 2 with the June 2015 Update\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/47481-Jun-25-2015-%28JST%29-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('the_kuftal_tour', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/The_Kuftal_Tour', function(quest)\n        quest.sections[2][xi.zone.KUFTAL_TUNNEL]['qm5'].onTrigger = function(player, npc)\n            local flag = true\n\n            for _, member in pairs(player:getAlliance()) do\n                if\n                    member:getMainLvl() > 40 or\n                    member:checkDistance(player) > 15\n                then\n                    flag = false\n                end\n            end\n\n            if flag and #player:getParty() == 6 then\n                return quest:progressEvent(14)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/the_missing_piece.lua"]={["Path"]="modules/era/lua/quests/outlands/the_missing_piece.lua",["SHA256"]="57f969d2c5d4ef8dde9e2471a9b62426c8a5eb822ebea6660a164f62fcf7d5c9",["Text"]="-----------------------------------\n-- The Missing Piece\n-- Restores the JST midnight wait before Charlaimagnat hands over the reward.\n-- The July 8, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_the_missing_piece', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/The_Missing_Piece', function(quest)\n        local sandoria   = quest.sections[2][xi.zone.NORTHERN_SAN_DORIA]\n        local baseTablet = sandoria.onEventFinish[703]\n\n        -- Charlaimagnat studies the tablet overnight. The reward is handed over at JST midnight.\n        sandoria.onEventFinish[703] = function(player, csid, option, npc)\n            baseTablet(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/the_sacred_katana.lua"]={["Path"]="modules/era/lua/quests/outlands/the_sacred_katana.lua",["SHA256"]="9f082e114b65af5b1f6a43d18af32f4bd0ec1bc332529f3a737991acf79f22b1",["Text"]="-----------------------------------\n-- The Sacred Katana (SAM AF1)\n-- Restores the JST midnight wait before Jaucribaix offers Yomi Okuri.\n-- The July 8, 2014 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_the_sacred_katana', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/SAM_AF1_The_Sacred_Katana', function(quest)\n        local norg = quest.sections[2][xi.zone.NORG]\n\n        -- Copy of the base handler. Yomi Okuri is offered at JST midnight.\n        norg.onEventFinish[141] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:tradeComplete()\n                player:delKeyItem(xi.keyItem.HANDFUL_OF_CRYSTAL_SCALES)\n\n                -- Player must zone before being able to flag the next quest\n                xi.quest.setMustZone(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI)\n                xi.quest.setVar(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/outlands/yomi_okuri.lua"]={["Path"]="modules/era/lua/quests/outlands/yomi_okuri.lua",["SHA256"]="39d8edf338fb8ea3bfada9c966f25127be6bf2b336abb6ff72cff65512bfcec3",["Text"]="-----------------------------------\n-- Yomi Okuri (SAM AF2)\n-- Restores the JST midnight wait before Jaucribaix hands over the yomotsu hirasaka.\n-- The same wait returns before he offers A Thief in Norg!?\n-- The July 8, 2014 version update shortened both to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_yomi_okuri', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/outlands/SAM_AF2_Yomi_Okuri', function(quest)\n        local norg          = quest.sections[2][xi.zone.NORG]\n        local baseFeatherCS = norg.onEventFinish[152]\n\n        -- The hirasaka is handed over at JST midnight.\n        norg.onEventFinish[152] = function(player, csid, option, npc)\n            baseFeatherCS(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n\n        -- Copy of the base handler. A Thief in Norg!? is offered at JST midnight.\n        norg.onEventFinish[156] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:delKeyItem(xi.keyItem.FADED_YOMOTSU_HIRASAKA)\n                xi.quest.setMustZone(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG)\n                xi.quest.setVar(player, xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG, 'Timer', JstMidnight()) -- Module change\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/advanced_teamwork.lua"]={["Path"]="modules/era/lua/quests/sandoria/advanced_teamwork.lua",["SHA256"]="db3b8fdf9533bc31c88f5f12677401a02892f076b641e17a825a98fc2b7bb1c1",["Text"]="-----------------------------------\n-- Advanced Teamwork\n-- Reverts the required number of same-job party members to six.\n-- The May 14, 2015 version update reduced the requirement to two.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46976\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_advanced_teamwork', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Advanced_Teamwork', function(quest)\n        -- Copy of the base handler with partySizeRequirement raised to 6\n        quest.sections[2][xi.zone.WEST_RONFAURE].onEventUpdate[129] = function(player, csid, option, npc)\n            local partySizeRequirement = 6\n            local party = player:getParty()\n            local partySameJobCount = 0\n\n            if #party >= partySizeRequirement then\n                for key, member in pairs(party) do\n                    if\n                        member:getZoneID() ~= player:getZoneID() or\n                        member:checkDistance(player) > 15\n                    then\n                        player:updateEvent(1)\n                        return\n                    else\n                        if player:getMainJob() == member:getMainJob() then\n                            partySameJobCount = partySameJobCount + 1\n                        end\n                    end\n                end\n            else\n                player:updateEvent(1)\n                return\n            end\n\n            if partySameJobCount == partySizeRequirement then\n                quest:setLocalVar(player, 'Prog', 1)\n                player:updateEvent(15, 3)\n                return\n            else\n                player:updateEvent(5, 3)\n                return\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/chasing_quotas.lua"]={["Path"]="modules/era/lua/quests/sandoria/chasing_quotas.lua",["SHA256"]="5fca6b712809f5c6d3a797bf12b346fd4e601299e655490c5278f6ff29dac8d0",["Text"]="-----------------------------------\n-- Chasing Quotas (DRG AF2)\n-- Restores the JST midnight wait before Ceraulian discovers the mugging.\n-- The February 19, 2015 version update shortened the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46068-Feb-19-2015-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_chasing_quotas', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Chasing_Quotas', function(quest)\n        local portSandoria = quest.sections[2][xi.zone.PORT_SAN_DORIA]\n        local baseTradeCS  = portSandoria.onEventFinish[17]\n\n        -- The mugging is discovered at JST midnight.\n        portSandoria.onEventFinish[17] = function(player, csid, option, npc)\n            baseTradeCS(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/eco_warrior.lua"]={["Path"]="modules/era/lua/quests/sandoria/eco_warrior.lua",["SHA256"]="821391e91a99a2af614de750836de825a90621cecccef3893148814de5e5f121",["Text"]="-----------------------------------\n-- Eco-Warrior (San d'Oria)\n-- Restores the level 20 restriction on the ointment.\n-- The June 25, 2015 version update raised the level cap from 20 to 25.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/47481\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_eco_warrior_sandoria', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Eco_Warrior', function(quest)\n        local ordellesCaves = quest.sections[2][xi.zone.ORDELLES_CAVES]\n\n        -- Copy of the base handler with the level restriction lowered to 20.\n        ordellesCaves.onEventFinish[51] = function(player, csid, option, npc)\n            if option == 1 then\n                player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                    power    = 20, -- Module change: the level restriction is 20.\n                    subPower = 1,  -- exp uses actual level and not the restricted level.\n                    origin   = player,\n                    flag     = xi.effectFlag.ON_ZONE\n                })\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/enveloped_in_darkness.lua"]={["Path"]="modules/era/lua/quests/sandoria/enveloped_in_darkness.lua",["SHA256"]="121991058393290cd24e5ba42e6f599f4df4714633fbe62dd5571cd5aa23385f",["Text"]="-----------------------------------\n-- Enveloped in Darkness (RDM AF2)\n-- Restores the JST midnight wait for the boots and crawler blood buried\n-- at the digging spot in the Crawlers' Nest.\n-- The June 17, 2014 version update shortened the wait to about 30 seconds.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_enveloped_in_darkness', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/RDM_AF2_Enveloped_in_Darkness', function(quest)\n        local crawlersNest = quest.sections[2][xi.zone.CRAWLERS_NEST]\n\n        -- Copy of the base handler with the 30 second wait extended to JST midnight.\n        crawlersNest.onEventFinish[4] = function(player, csid, option, npc)\n            if option == 1 then\n                -- Set purification time.\n                quest:setVar(player, 'Time', JstMidnight()) -- Module change: the boots are purified at JST midnight.\n\n                -- Delete Key items.\n                player:delKeyItem(xi.keyItem.CRAWLER_BLOOD)\n                player:delKeyItem(xi.keyItem.OLD_BOOTS)\n\n                -- Message when acepting to bury boots and blood.\n                player:messageSpecial(zones[xi.zone.CRAWLERS_NEST].text.YOU_BURY_THE, xi.keyItem.OLD_BOOTS, xi.keyItem.CRAWLER_BLOOD)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/intermediate_teamwork.lua"]={["Path"]="modules/era/lua/quests/sandoria/intermediate_teamwork.lua",["SHA256"]="01adf713526be5956e9dc06ee27bc82d9e2cc77113e2cdbdd8d5f2e65d3cc107",["Text"]="-----------------------------------\n-- Intermediate Teamwork\n-- Reverts the required number of same-race party members to six.\n-- The May 14, 2015 version update reduced the requirement to two.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46976\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_intermediate_teamwork', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Intermediate_Teamwork', function(quest)\n        -- Copy of the base handler with partySizeRequirement raised to 6\n        quest.sections[2][xi.zone.WEST_RONFAURE].onEventUpdate[129] = function(player, csid, option, npc)\n            local partySizeRequirement = 6\n            local party = player:getParty()\n            local partySameRaceCount = 0\n\n            if #party >= partySizeRequirement then\n                for key, member in pairs(party) do\n                    if\n                        member:getZoneID() ~= player:getZoneID() or\n                        member:checkDistance(player) > 15\n                    then\n                        player:updateEvent(1)\n                        return\n                    else\n                        local pRace = player:getRace()\n                        local mRace = member:getRace()\n\n                        if\n                            (pRace == xi.race.HUME_M or pRace == xi.race.HUME_F) and\n                            (mRace == xi.race.HUME_M or mRace == xi.race.HUME_F)\n                        then\n                            partySameRaceCount = partySameRaceCount + 1\n                        elseif\n                            (pRace == xi.race.ELVAAN_M or pRace == xi.race.ELVAAN_F) and\n                            (mRace == xi.race.ELVAAN_M or mRace == xi.race.ELVAAN_F)\n                        then\n                            partySameRaceCount = partySameRaceCount + 1\n                        elseif\n                            (pRace == xi.race.TARU_M or pRace == xi.race.TARU_F) and\n                            (mRace == xi.race.TARU_M or mRace == xi.race.TARU_F)\n                        then\n                            partySameRaceCount = partySameRaceCount + 1\n                        elseif pRace == xi.race.GALKA and mRace == xi.race.GALKA then\n                            partySameRaceCount = partySameRaceCount + 1\n                        elseif pRace == xi.race.MITHRA and mRace == xi.race.MITHRA then\n                            partySameRaceCount = partySameRaceCount + 1\n                        end\n                    end\n                end\n            else\n                player:updateEvent(1)\n                return\n            end\n\n            if partySameRaceCount >= partySizeRequirement then\n                quest:setLocalVar(player, 'Prog', 1)\n                player:updateEvent(15, 2)\n                return\n            else\n                player:updateEvent(4, 2)\n                return\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/sandoria/introduction_to_teamwork.lua"]={["Path"]="modules/era/lua/quests/sandoria/introduction_to_teamwork.lua",["SHA256"]="1504d2938756151fa1f28435a6727f14a2da11d6ec8e3ee25e4f45a991b21a04",["Text"]="-----------------------------------\n-- Introduction to Teamwork\n-- Reverts the required number of same-nation party members to six.\n-- The May 14, 2015 version update reduced the requirement to two.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/46976\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_introduction_to_teamwork', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/sandoria/Introduction_to_Teamwork', function(quest)\n        -- Copy of the base handler with partySizeRequirement raised to 6\n        quest.sections[2][xi.zone.WEST_RONFAURE].onEventUpdate[129] = function(player, csid, option, npc)\n            local partySizeRequirement = 6\n            local party = player:getParty()\n            local partySameNationCount = 0\n\n            if #party >= partySizeRequirement then\n                for key, member in pairs(party) do\n                    if\n                        member:getZoneID() ~= player:getZoneID() or\n                        member:checkDistance(player) > 15\n                    then\n                        player:updateEvent(1)\n                        return\n                    else\n                        if member:getNation() == player:getNation() then\n                            partySameNationCount = partySameNationCount + 1\n                        end\n                    end\n                end\n            else\n                player:updateEvent(1)\n                return\n            end\n\n            if partySameNationCount >= partySizeRequirement then\n                quest:setLocalVar(player, 'Prog', 1)\n                player:updateEvent(15, 1)\n                return\n            else\n                player:updateEvent(3, 1)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/windurst/a_greeting_cardian.lua"]={["Path"]="modules/era/lua/quests/windurst/a_greeting_cardian.lua",["SHA256"]="6168826e951edd2623575fd3c1fa6c1b2bdea4a75817991653528e4faed2ddc1",["Text"]="-----------------------------------\n-- A Greeting Cardian\n-- Restores the JST midnight wait before Kororo offers the quest.\n-- The July 8, 2014 version update shortened the wait to one minute.\n-- The zone change after the teaching is still live on retail. It stays in the base script.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_a_greeting_cardian', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/A_Greeting_Cardian', function(quest)\n        local woods       = quest.sections[1][xi.zone.WINDURST_WOODS]\n        local baseTeachCS = woods.onEventFinish[295]\n\n        -- Kororo makes the offer at JST midnight, after the zone change.\n        woods.onEventFinish[295] = function(player, csid, option, npc)\n            baseTeachCS(player, csid, option, npc)\n            quest:setVar(player, 'Wait', JstMidnight()) -- Module change\n        end\n    end)\nend)\n"},["modules/era/lua/quests/windurst/blue_ribbon_blues.lua"]={["Path"]="modules/era/lua/quests/windurst/blue_ribbon_blues.lua",["SHA256"]="717f9dac2e81a7533c3acb4a2b7bf4fdbffcc45b31238dc869f647c2f7978b35",["Text"]="-----------------------------------\n-- Blue Ribbon Blues\n-- Restores the JST midnight wait, and the zone change, before Kerutoto returns the purple ribbon.\n-- The July 8, 2014 version update replaced both conditions with a flat wait, mistakenly one hour long.\n-- The November 10, 2014 update corrected the wait to one minute.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/43135-Jul-8-2014-(JST)-Version-Update\n-- Source: https://wiki.ffo.jp/html/10406.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_blue_ribbon_blues', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/Blue_Ribbon_Blues', function(quest)\n        local watersOffer   = quest.sections[1][xi.zone.WINDURST_WATERS]\n        local watersAccept  = quest.sections[2][xi.zone.WINDURST_WATERS]\n        local baseFirstCS   = watersOffer.onEventFinish[358]\n        local baseRetradeCS = watersAccept.onEventFinish[365]\n\n        -- Kerutoto keeps the ribbon overnight, and only hands it back once the player has also zoned.\n        watersOffer.onEventFinish[358] = function(player, csid, option, npc)\n            baseFirstCS(player, csid, option, npc)\n            quest:setVar(player, 'Timer', JstMidnight()) -- Module change\n            quest:setMustZone(player) -- Module change\n        end\n\n        -- The player can hand the ribbon back a second time, which restarts the same wait.\n        watersAccept.onEventFinish[365] = function(player, csid, option, npc)\n            baseRetradeCS(player, csid, option, npc)\n            quest:setVar(player, 'Timer', JstMidnight()) -- Module change\n            quest:setMustZone(player) -- Module change\n        end\n\n        -- Copy of the base handler, with the zone change added to the wait branch.\n        watersAccept['Kerutoto'].onTrigger = function(player, npc)\n            local questProgress = quest:getVar(player, 'Prog')\n\n            if questProgress == 0 then\n                if\n                    GetSystemTime() < quest:getVar(player, 'Timer') or\n                    quest:getMustZone(player) -- Module change\n                then\n                    return quest:progressEvent(359)\n                else\n                    return quest:progressEvent(360)\n                end\n            elseif questProgress == 1 then\n                if not player:findItem(xi.item.PURPLE_RIBBON) then\n                    return quest:progressEvent(366, 0, xi.item.PURPLE_RIBBON)\n                else\n                    return quest:progressEvent(361, 0, xi.item.PURPLE_RIBBON)\n                end\n            elseif questProgress == 3 then\n                return quest:progressEvent(362)\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/windurst/eco_warrior.lua"]={["Path"]="modules/era/lua/quests/windurst/eco_warrior.lua",["SHA256"]="51937c8c168b01e3f93e423cba13454502178f0f1e2a0d2b37274828325accf2",["Text"]="-----------------------------------\n-- Eco-Warrior (Windurst)\n-- Restores the level 20 restriction on the ointment.\n-- The June 25, 2015 version update raised the level cap from 20 to 25.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/47481\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_eco_warrior_windurst', xi.pre(xi.expansion.ROV))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/Eco_Warrior', function(quest)\n        local mazeOfShakhrami = quest.sections[2][xi.zone.MAZE_OF_SHAKHRAMI]\n\n        -- Copy of the base handler with the level restriction lowered to 20.\n        mazeOfShakhrami.onEventFinish[62] = function(player, csid, option, npc)\n            if option == 1 then\n                player:addStatusEffect(xi.effect.LEVEL_RESTRICTION, {\n                    power    = 20, -- Module change: the level restriction is 20.\n                    subPower = 1,  -- exp uses actual level and not the restricted level.\n                    origin   = player,\n                    flag     = xi.effectFlag.ON_ZONE\n                })\n            end\n        end\n    end)\nend)\n"},["modules/era/lua/quests/windurst/sin_hunting.lua"]={["Path"]="modules/era/lua/quests/windurst/sin_hunting.lua",["SHA256"]="e471cd4e5f23ae2269815de0421bafb3a2c6688dd21c5326379a2103bc05cc64",["Text"]="-----------------------------------\n-- Sin Hunting\n-- Restores the full moon requirement to examine the ??? in Jugner Forest.\n-- The June 17, 2014 version update changed the event to occur regardless\n-- of Vana'diel time and phase of the moon.\n-----------------------------------\n-- Source: https://forum.square-enix.com/ffxi/threads/42614-Jun-17-2014-(JST)-Version-Update\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_quest_sin_hunting', xi.pre(xi.expansion.SOA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/windurst/RNG_AF1_Sin_Hunting', function(quest)\n        local jugnerForest  = quest.sections[2][xi.zone.JUGNER_FOREST]\n        local baseOnTrigger = jugnerForest['qm2'].onTrigger\n\n        jugnerForest['qm2'].onTrigger = function(player, npc)\n            if getVanadielMoonCycle() == xi.moonCycle.FULL_MOON then\n                return baseOnTrigger(player, npc)\n            end\n        end\n    end)\nend)\n"}};
